// === FIXED-SIZE WINDOW ===
function fixedWindow(arr, k) {
  let state = 0;
  // build initial window
  for (let i = 0; i < k; i++) state += arr[i];
  let best = state;
  for (let right = k; right < arr.length; right++) {
    state += arr[right] - arr[right - k]; // slide: add new, remove old
    best = Math.max(best, state);
  }
  return best;
}

// === VARIABLE-SIZE WINDOW ===
function variableWindow(s) {
  const freq = new Map();
  let left = 0, best = 0;

  for (let right = 0; right < s.length; right++) {
    // expand: add s[right] into window state
    freq.set(s[right], (freq.get(s[right]) || 0) + 1);

    // shrink: move left until window is valid again
    while (/* window invalid condition */ freq.size > 2) {
      const lc = s[left++];
      freq.set(lc, freq.get(lc) - 1);
      if (freq.get(lc) === 0) freq.delete(lc);
    }

    // window [left..right] is now the largest valid window ending at right
    best = Math.max(best, right - left + 1);
  }
  return best;
}
